ca_aes_ecb_selftest.example:
/* Example: Running the AES self-test during system initialization */
#include "caos.h"

void run_security_diagnostics(void) {
    u32 failures = 0;

    /* Ensure the AES subsystem is ready before testing */
    ca_aes_init();

    /* Execute the ECB self-test */
    failures = ca_aes_ecb_selftest();

    if (failures > 0) {
        /* Log the failure to the system console */
        ca_stdout_printf_n("Security check failed with %u errors", failures);
        /* Halt or enter a safe state if crypto is broken */
        while(1) { ca_os_yield(); }
    } else {
        ca_stdout_put_n("Security subsystem verified.");
    }
}

