{
    /* Check if we already have this IP in our cache to avoid unnecessary writes */
    if (!ca_arp_find(sender_ip, NULL)) {
        /* Update the ARP cache with the new mapping */
        ca_arp_learn(sender_ip, sender_mac);

        /* Log the event for debugging purposes */
        ca_printf("Learned new ARP entry: %d.%d.%d.%d\n", 
                  (int)sender_ip.a, (int)sender_ip.b, 
                  (int)sender_ip.c, (int)sender_ip.d);
    }
}

