/* Typical initialization sequence in ca_os_main */
void ca_os_main(void) {
    ca_mac_t my_mac = { .addr = {0x00, 0x11, 0x22, 0x33, 0x44, 0x55} };
    ca_ipv4_t my_ip = { .addr = 0x00000000 }; // Will be updated via DHCP later

    // 1. Initialize hardware and network interface
    eth_gpio_init();
    ca_net_init(ca_eth_iface_get(&eth_cfg));

    // 2. Initialize ARP service before starting network tasks
    ca_arp_service_init(my_mac, my_ip);

    // 3. Start the service and background tasks
    ca_arp_service_start();

    // 4. Proceed to spawn application tasks
    ca_os_job("net", CA_TH_LEVEL2, task_net, 0, STACK_SMALL, CA_JOB_STD, CA_FAULT_RESTART_THREAD);
}

