void ca_os_main(void) {
    // 1. Configure the network identity first
    // Assuming s_mac and s_ip are defined globally
    ca_arp_service_init(s_mac, s_ip);

    // 2. Start the ARP service task
    // This registers the task with the scheduler
    ca_arp_service_start();

    // 3. Start other dependent services
    ca_udp_server_start(&srv_cfg);

    // 4. Proceed to launch other application tasks
    ca_os_job("app_task", CA_TH_LEVEL5, my_app_task, 0, STACK_SMALL, CA_JOB_STD, CA_FAULT_RESTART_THREAD);
}

