ca_barrier_init.example:
ca_barrier_t bar;
#define N_WORKERS 3

void system_init(void) {
    /* Initialize the barrier for 3 workers before starting tasks */
    ca_barrier_init(&bar, N_WORKERS);

    /* Now it is safe to spawn threads that will use this barrier */
    ca_os_job("worker1", CA_TH_LEVEL2, worker_task, NULL, STACK_SMALL, CA_JOB_STD, CA_FAULT_ASSERT);
    ca_os_job("worker2", CA_TH_LEVEL2, worker_task, NULL, STACK_SMALL, CA_JOB_STD, CA_FAULT_ASSERT);
    ca_os_job("worker3", CA_TH_LEVEL2, worker_task, NULL, STACK_SMALL, CA_JOB_STD, CA_FAULT_ASSERT);
}

void worker_task(void *arg) {
    /* Each worker performs work and then waits for others */
    /* Call the barrier wait function to synchronize with other threads */
    ca_barrier_wait(&bar);
}

ca_barrier_wait.example:
/* Example: Synchronizing 3 worker threads */
ca_barrier_t bar;

void worker_task(void *arg) {
    /* Perform some work */
    ca_os_sleep(50u);

    /* Wait for all 3 workers to reach this point */
    bool is_last = ca_barrier_wait(&bar);

    if (is_last) {
        /* Only the last thread executes this cleanup */
        ca_stdout_printf_n("All workers finished, proceeding to next phase.");
    }

    /* All threads continue here after the barrier is released */
    /* Proceed to next processing stage */
}

