/* Example: Safely writing a status marker to the last available backup register */
#include "caos.h"

void log_system_status(u32 status_code) {
    u32 count = ca_bkp_count();

    /* Ensure we have at least one register to avoid underflow */
    if (count > 0) {
        /* Use the last register index (zero-based) */
        u32 last_idx = count - 1U;

        /* Write the status code to the hardware backup register */
        ca_bkp_write(last_idx, status_code);
    } else {
        /* Handle case where no backup registers are available */
        ca_printf("Error: No backup registers available to log status.\n");
    }
}

