void save_system_state(u32 state_flag) {
    /* Check if the index is valid before writing */
    if (ca_bkp_count() > 0) {
        /* Lock the scheduler to ensure atomic access to the backup domain */
        ca_os_sched_lock();

        /* Write the state to the first backup register (index 0) */
        ca_bkp_write(0, state_flag);

        ca_os_sched_unlock();
    } else {
        /* Handle error: no backup registers available */
    }
}

