u16 process_network_data(u8 *buffer) {
    /* Combine two bytes into a 16-bit value (little-endian construction) */
    u16 raw_val = (u16)(((u16)buffer[1] << 8) | (u16)buffer[0]);

    /* If the network protocol is big-endian, swap the bytes to host order */
    u16 host_val = ca_bswap16(raw_val);

    return host_val;
}

