ca_bswap32.example:
#include "caos.h"

// Example: Reading a 32-bit Big-Endian value from a buffer
void process_network_data(u8 *buffer) {
    u32 raw_val;
    u32 host_val;

    // Assemble 4 bytes from buffer into a 32-bit integer (Big-Endian order)
    raw_val = ((u32)buffer[0] << 24) | ((u32)buffer[1] << 16) | 
              ((u32)buffer[2] << 8)  | ((u32)buffer[3]);

    // Convert from Big-Endian (network) to Little-Endian (host)
    host_val = ca_bswap32(raw_val);

    // Log the result using caOS logging
    ca_printf("Converted value: %u\n", host_val);
}

