u64 process_network_timestamp(u8 *buffer) {
    u64 raw_val;
    /* Copy raw bytes from buffer into a 64-bit variable */
    ca_memcpy(&raw_val, buffer, sizeof(u64));

    /* 
     * Assuming the network protocol is Big-Endian, 
     * we must swap bytes to match the STM32 Little-Endian format. 
     */
    u64 host_val = ca_bswap64(raw_val);

    return host_val;
}

ca_bswap64_signed.example:
/* Example: Processing a 64-bit timestamp received from a network buffer */
#include "caos.h"

i64 process_network_timestamp(void *buffer) {
    i64 raw_data;

    /* Copy raw bytes from the buffer into our local variable */
    ca_memcpy(&raw_data, buffer, sizeof(i64));

    /* 
     * The network sends data in Big-Endian, but our STM32 is Little-Endian.
     * We must swap the bytes to get the correct signed integer value.
     */
    i64 host_timestamp = ca_bswap64_signed(raw_data);

    return host_timestamp;
}

