/* Example: Navigating CLI history using the count */

void navigate_history(i8 *current_nav_index, i8 direction) {
    u8 total_hist = ca_cli_hist_count();

    if (total_hist == 0) return; // Nothing to navigate

    if (direction > 0) { // Moving to older commands
        if (*current_nav_index < (i8)(total_hist - 1)) {
            (*current_nav_index)++;
            const char *cmd = ca_cli_hist_get((u8)*current_nav_index);
            if (cmd) {
                /* Use ca_printf to display the recalled command */
            }
        }
    } else if (direction < 0) { // Moving to newer commands
        if (*current_nav_index > 0) {
            (*current_nav_index)--;
            const char *cmd = ca_cli_hist_get((u8)*current_nav_index);
            if (cmd) {
                /* Use ca_printf to display the recalled command */
            }
        }
    }
}

