void atomic_increment_example(uint32_t *addr) {
    uint32_t val;
    /* Load the value exclusively */
    val = ca_ldrex(addr);

    /* Check if the value is valid for our logic */
    if (val == 0xFFFFFFFF) {
        /* We cannot increment, so we must clear the monitor before exiting */
        ca_clrex();
        return;
    }

    /* Attempt to store the incremented value */
    if (ca_strex(addr, val + 1) != 0) {
        /* Store failed, monitor is automatically cleared by hardware on failure */
    }
}

