/* Assuming s_cv is a globally accessible condition variable and s_mtx is a mutex */
void notify_all_workers(void) {
    /* Lock the mutex to ensure exclusive access to the shared condition */
    ca_mutex_lock(&s_mtx);

    /* Update the shared state that the waiters are checking */
    /* shared_data_ready = true; */

    /* Wake up all tasks waiting for the data to be ready */
    ca_cond_broadcast(&s_cv);

    /* Release the mutex so the woken tasks can proceed to lock it */
    ca_mutex_unlock(&s_mtx);
}

/* In a worker task */
void worker_task(void) {
    while(1) {
        ca_mutex_lock(&s_mtx);
        /* Always use a while loop to handle spurious wakeups */
        while(/* !shared_data_ready */ 0) {
            ca_cond_wait(&s_cv, &s_mtx);
        }
        /* Process the data once woken */
        ca_mutex_unlock(&s_mtx);
    }
}

