/* Example: Triggering a DHCP renewal when the network link is restored */

void monitor_network_task(void) {
    bool link_up = false;

    while (1) {
        /* Check if the physical network link is active */
        bool current_link = ca_net_link_status();

        /* If link just came up and we were previously bound, request a renewal */
        if (current_link && !link_up && ca_dhcp_service_bound()) {
            ca_stdout_put_n("Link restored, requesting DHCP renewal");
            ca_dhcp_service_renew();
        }

        link_up = current_link;
        ca_os_sleep(500);
    }
}

