/* Example of calling the handler within a network receive callback */
void my_network_rx_callback(u16 buf_idx) {
    /* Retrieve buffer metadata and pointer using internal stack access */
    /* Assume 'b' is the buffer pointer retrieved from the stack */
    u8 *frame = b->data + b->data_off;
    u16 l4_off = b->meta.rx.l4_off;
    const ca_udp_frame_t *udp = (const ca_udp_frame_t *)(frame + l4_off);
    u16 udp_total = (u16)(b->data_len - l4_off);

    /* Process the DHCP packet */
    ca_dhcp_service_rx_handler(udp, udp_total);

    /* Crucial: release the buffer back to the network stack */
    ca_net_buf_free(buf_idx);
}

