/* Example: Aborting a DMA transfer due to a timeout */
void handle_dma_timeout(ca_dma_ch_t ch) {
    /* Convert the channel handle to the internal flat index */
    u8 flat = ca_dma_hw_ch_to_flat(ch);

    /* Stop the hardware immediately */
    ca_dma_hw_abort(flat);

    /* 
     * After the hardware is stopped, we must ensure the software 
     * state is consistent. We drain any pending semaphores that 
     * might have been waiting for a completion that will never arrive.
     */
    dma_sem_drain(flat);

    /* Log the event or notify the system that the transfer was cancelled */
    ca_printf("DMA channel %d aborted due to timeout\n", flat);
}

