/* Background task to monitor Ethernet link status */
void eth_monitor_task(void *arg) {
    /* Ensure Ethernet hardware is initialized before polling */
    /* ca_eth_init(&eth_cfg); */

    while (1) {
        bool link_is_up = ca_eth_link_poll();

        if (link_is_up) {
            /* If link just came up, announce our IP via GARP */
            ca_arp_send_garp();
            ca_stdout_printf_n("Ethernet link is UP");
        } else {
            ca_stdout_printf_n("Ethernet link is DOWN");
        }

        /* Wait 500ms before polling again to avoid bus congestion */
        ca_os_sleep(500);
    }
}

