    /* Read the Basic Status Register (Register 1) */
    u16 status = ca_eth_phy_read(phy_addr, 1);

    /* Check if the link status bit (bit 2) is set */
    if (status & 0x0004) {
        /* Use ca_printf to log the status */
        ca_printf("Link is UP on PHY %d\n", phy_addr);
    } else {
        ca_printf("Link is DOWN on PHY %d\n", phy_addr);
