/* Example: Configuring the PHY to force 100Mbps Full Duplex */
#define PHY_ADDR 0x01
#define BMCR_REG 0x00
#define BMCR_FORCE_100_FD 0x2100

void setup_ethernet_link(void) {
    /* Read current configuration */
    u16 reg_val = ca_eth_phy_read(PHY_ADDR, BMCR_REG);

    /* Modify bits to force speed and duplex */
    reg_val |= BMCR_FORCE_100_FD;

    /* Write back the updated configuration to the PHY */
    ca_eth_phy_write(PHY_ADDR, BMCR_REG, reg_val);

    /* Ensure the link is polled after configuration */
    ca_eth_link_poll();
}

ca_eth_pool_held_count.example:
/* Check for potential memory leaks in the network buffer pool */

void check_network_health(void) {
    u16 free_bufs = ca_net_buf_free_count();
    u16 held_bufs = ca_eth_pool_held_count();
    /* Assume NET_BUF_COUNT is defined as the total system buffer capacity */
    u16 total_bufs = (u16)NET_BUF_COUNT;

    /* Calculate if any buffers are 'lost' (leaked) */
    if ((free_bufs + held_bufs) < total_bufs) {
        u16 leaked = (u16)(total_bufs - free_bufs - held_bufs);
        ca_printf_n("Warning: %u buffers leaked!", (u32)leaked);
        /* Trigger a debug dump to inspect hardware state */
        ca_eth_dbg_dump();
    } else {
        ca_printf_n("System healthy: %u free, %u held.", (u32)free_bufs, (u32)held_bufs);
    }
}

