ca_flash_hw_start_write_irq.example:
/* Example of writing a buffer to flash memory */
u32 addr = 0x08020000; /* Target flash address */
u8 data[] = {0xDE, 0xAD, 0xBE, 0xEF}; /* Data to write */
u32 len = 4;
u32 off = 0;

while (off < len) {
    /* Start the write for the current chunk */
    u32 consumed = ca_flash_hw_start_write_irq(addr + off, data + off, len - off);

    if (consumed == 0) {
        /* Handle error: hardware failed to start write */
        break;
    }

    /* Wait for the EOP interrupt to signal completion */
    ca_sem_wait(&g_flash_sem);

    /* Check if the hardware reported an error during the write */
    if (g_flash_error) {
        break;
    }

    off += consumed;
}

