#define DATA_LEN 8

void compute_secure_tag(void) {
    ca_sha512_ctx_t ctx;
    u8 key[HMAC_KEY_LEN];
    u8 mac[48]; /* SHA384 digest size is 48 bytes */
    const u8 *data = (const u8 *)"SecretMsg";

    /* Initialize key with dummy data */
    ca_memset(key, 0xAA, HMAC_KEY_LEN);

    /* Compute the HMAC */
    ca_hmac_sha384_ctx(&ctx, key, HMAC_KEY_LEN, data, DATA_LEN, mac);

    /* Clear sensitive data from memory immediately after use */
    ca_memzero(key, HMAC_KEY_LEN);
    ca_memzero(&ctx, sizeof(ca_sha512_ctx_t));
}

