void process_image_data(const u8 *data, u32 total_words) {
    u32 buffer[BURST_SIZE];
    u32 remaining = total_words;
    const u32 *ptr = (const u32 *)data;

    /* Ensure JPEG hardware is initialized before use */
    ca_jpeg_init();

    while (remaining > 0) {
        u32 chunk = (remaining > BURST_SIZE) ? BURST_SIZE : remaining;

        /* Copy data to local buffer to ensure alignment */
        ca_memcpy(buffer, ptr, chunk * 4U);

        /* Write the burst of words to the hardware FIFO */
        ca_jpeg_hw_put_n(buffer, chunk);

        ptr += chunk;
        remaining -= chunk;
    }
}

