/* Example: Shifting data in a buffer after processing a header */
#include "caos.h"

void process_buffer(u8 *buffer, u32 *current_size) {
    u32 header_size = 4;
    if (*current_size > header_size) {
        /* Move remaining data to the start of the buffer, overwriting the header */
        /* This is safe even though source and destination overlap */
        ca_memmove(buffer, &buffer[header_size], *current_size - header_size);

        /* Update the size tracker */
        *current_size -= header_size;
    } else {
        /* Clear the buffer if no data remains */
        ca_memset(buffer, 0, *current_size);
        *current_size = 0;
    }
}

