ca_net_buf_free.example:
/* Example: Allocate a buffer, attempt to build a packet, and free on failure */
u16 idx = ca_net_buf_alloc();
if (idx < NET_BUF_COUNT) {
    ca_net_buf_t *b = ca_net_buf_ptr(idx);
    u8 *out = b->data + NET_BUF_HEADROOM;

    /* Use ca_net_proto_arp_build_garp to fill the buffer */
    u16 len = ca_net_proto_arp_build_garp(s_local_mac, s_local_ip, out);

    if (len == 0U) {
        /* Construction failed, release the buffer back to the pool */
        ca_net_buf_free(idx);
    } else {
        b->data_off = NET_BUF_HEADROOM;
        b->data_len = len;
        /* Send the packet; the driver will eventually free the buffer */
        if (ca_net_send(idx) != 0U) {
            /* If send fails, we must free it manually */
            ca_net_buf_free(idx);
        }
    }
}

