/* Early system initialization sequence */
void system_startup(void) {
    /* Configure the main system clock tree */
    int status = ca_os_clock_config();
    if (status != 0) {
        /* Handle clock failure: enter safe mode or trap */
        while(1);
    }

    /* Update internal variables to reflect the new frequency */
    SystemCoreClockUpdate();

    /* Adjust OS tick to match the new clock frequency */
    ca_os_tick_retune();

    /* Re-initialize peripherals that depend on clock speed */
    ca_uart_retune();

    /* Now safe to start OS services */
    ca_os_run();
}

