void handle_thermal_event(void) {
    u32 new_freq;

    /* Reduce clock to 50% to lower heat generation */
    new_freq = ca_os_clock_reduce_freq(50);

    /* Critical: Retune system timing and peripherals to match new clock */
    ca_os_tick_retune();
    ca_uart_retune();

    /* Log the change to the console */
    ca_printf("System clock reduced to %lu Hz\r\n", new_freq);

    /* Perform low-power operations... */

    /* Restore original clock when safe */
    ca_os_clock_restore_freq();
    ca_os_tick_retune();
    ca_uart_retune();
}

