    if (ca_queue_heap_is_empty(&my_queue)) {
        // Prepare to sleep if no data is present
        u32 status = ca_os_sleep_prepare(ticks);
        ca_spinlock_unlock_irq(&my_lock);

        // If preparation succeeded, yield control to the scheduler
        if (status == 0U) {
            ca_os_yield();
        }
    } else {
        ca_spinlock_unlock_irq(&my_lock);
    }
}

