    ca_enter_critical();

    // Stop the SysTick to prevent it from waking the CPU prematurely
    ca_os_tick_suspend();

    // Ensure all memory operations are complete before sleeping
    __DSB();

    // Enter low power mode (e.g., WFI instruction)
    // The CPU will wait here until an external interrupt occurs
    __WFI();

    // Wake up: restore the system tick to resume RTOS scheduling
    ca_os_tick_resume();

    // Re-enable interrupts to allow normal operation
    ca_exit_critical();
}

