/* Example: Waiting for a custom condition under a spinlock */
void wait_for_custom_event(void) {
    ca_spinlock_lock_irq(&my_lock);

    /* Check condition: if false, prepare to block */
    while (my_condition == 0) {
        /* ca_os_wait_prepare() handles the internal blocking logic */
        u32 parked = ca_os_wait_prepare();

        /* Release lock so others can signal us */
        ca_spinlock_unlock_irq(&my_lock);

        /* If we were successfully parked, yield to let other tasks run */
        if (parked == 0U) {
            ca_os_yield();
        }

        /* Re-acquire the lock to check the condition again */
        ca_spinlock_lock_irq(&my_lock);
    }

    /* Condition met, proceed with work */
    my_condition = 0;
    ca_spinlock_unlock_irq(&my_lock);
}

