static void recursive_worker(int depth) {
    /* Acquire the lock; if already held by this thread, count increments */
    ca_rmutex_lock(&rmtx);

    ca_stdout_printf_n("Depth: %d, Lock count: %u", depth, ca_rmutex_get_count(&rmtx));

    if (depth > 0) {
        recursive_worker(depth - 1);
    }

    /* Release the lock; must match the number of locks acquired */
    ca_rmutex_unlock(&rmtx);
}

void task_entry(void *arg) {
    ca_rmutex_init(&rmtx);
    while (1) {
        recursive_worker(3);
        ca_os_delay_ms(1000);
