/* Define the lock globally or in a persistent scope */
ca_rwlock_t my_data_lock;

void task_init_routine(void) {
    /* Initialize the lock before any task attempts to use it */
    ca_rwlock_init(&my_data_lock);
}

void reader_task(void) {
    /* Acquire read access: multiple readers can hold this simultaneously */
    ca_rwlock_read_lock(&my_data_lock);
    /* Perform read operations on shared data here */
    ca_rwlock_read_unlock(&my_data_lock);
}

void writer_task(void) {
    /* Acquire write access: exclusive access, blocks all readers and other writers */
    ca_rwlock_write_lock(&my_data_lock);
    /* Perform write operations on shared data here */
    ca_rwlock_write_unlock(&my_data_lock);
}

