}

ca_rwlock_owner_gone.example:
/* Example of how the OS handles a task termination cleanup */
void task_cleanup_routine(ca_thread_context_t *ctx) {
    /* Ensure the task is no longer scheduled */
    ca_os_suspend_handle(ca_os_task_handle(ctx));

    /* Release any mutexes the task was holding */
    ca_mutex_owner_gone(ctx);

    /* Release any read/write locks the task was holding */
    /* This prevents other tasks from waiting forever on a dead owner */
    ca_rwlock_owner_gone(ctx);

    /* Finally, free memory owned by the task */
    ca_memory_free_all_owned_by(ctx);
}

