        /* Check stack usage every 5000 ticks to save CPU */
        if ((u32)(ca_os_tick() - last_check) > 5000) {
            ca_scheduler_update_all_stack_usage();
            last_check = ca_os_tick();
        }
        /* Perform other background maintenance */
        ca_os_yield();
    }
}

