}

void safe_free_operation(ca_block_pool_t *pool, void *ptr) {
    /* Enter critical section: lock and disable interrupts */
    ca_spinlock_lock_irq(&my_lock);

    /* Perform the atomic operation on the pool */
    ca_block_free(pool, ptr);

    /* Exit critical section: release lock and restore interrupts */
    ca_spinlock_unlock_irq(&my_lock);
}

