void atomic_bit_set(volatile u32 *word, u32 bit_mask) {
    u32 current_val;
    do {
        /* Load current value and set exclusive monitor */
        current_val = ca_ldrex(word);
        /* Modify the value locally */
        current_val |= bit_mask;
        /* Attempt to store; if it fails, the loop retries */
    } while (ca_strex(word, current_val) != 0U);
    /* Ensure monitor is cleared if we exit early (good practice) */
    ca_clrex();
}

