void handle_cli_command(const char *p) {
    if (ca_strncmp(p, "set", 3) == 0) {
        /* Skip 'set' and leading spaces */
        p = ca_skip_sp(p + 3);

        /* Parse channel number (decimal) */
        u8 ch = (u8)ca_strtol(p, 10);

        /* Move pointer to the next argument */
        while (*p && *p != ' ') p++;

        /* Parse value (decimal) */
        u32 val = (u32)ca_strtol(ca_skip_sp(p), 10);

        /* Validate range before hardware interaction */
        if (ch >= 1 && ch <= 2 && val <= 4095U) {
            ca_dac_write(ch, (u16)val);
        } else {
            ca_printf_n("Invalid parameters");
        }
    }
}

