ca_tcp_is_connected.example:
u8 h = ca_tcp_connect(&cfg);
/* Verify handle is valid and connection is established */
if (h != 0U && ca_tcp_is_connected(h)) {
    u8 rx_buf[64];
    u16 got = 0U;
    /* Keep receiving as long as the connection is active */
    while (ca_tcp_is_connected(h)) {
        /* Attempt to receive data with a 1000ms timeout */
        if (ca_tcp_recv(h, rx_buf, sizeof(rx_buf), &got, 1000U) && got > 0U) {
            /* Process received data */
            ca_printf("Received %d bytes\n", got);
        } else {
            /* If recv fails, check if connection is still alive before breaking */
            if (!ca_tcp_is_connected(h)) {
                break;
            }
        }
    }
    /* Release resources after loop terminates */
    ca_tcp_close(h);
} else if (h != 0U) {
    /* Abort if connection failed to establish */
    ca_tcp_abort(h);
}

