ca_tcp_send.example:
i32 r;
u32 tries = 0U;
for (;;) {
    r = ca_tcp_send(h, buf, len);
    if (r == CA_TCP_SENT) break;                      /* whole buffer queued */
    if (r == CA_TCP_GONE || ++tries > 1000U) break;    /* connection gone */
    /* CA_TCP_RETRY: nothing was sent - wait for room, send the same again */
    if (!ca_tcp_wait_writable(h, 1000U) && !ca_tcp_is_connected(h)) break;
}
if (r != CA_TCP_SENT) {
    ca_tcp_close(h);
}

