#include "caos.h"

void send_data_via_dma(USART_TypeDef *uart_inst, ca_dma_ch_t tx_channel, uint8_t *data, uint16_t size) {
    /* Get the hardware register address for the UART TDR */
    volatile void *tx_reg_addr = ca_uart_hw_dma_tx_addr(uart_inst);

    if (tx_reg_addr != NULL) {
        /* Configure DMA to copy data from memory to the UART TDR register */
        if (ca_dma_copy_target(tx_channel, (void *)data, (void *)tx_reg_addr, size, CA_DMA_DIR_M2P, CA_DMA_WIDTH_8)) {
            /* Wait for the DMA transfer to complete before proceeding */
            ca_dma_wait(tx_channel);
        }
    }
}

