/* Example: Performing a clean reset of the MicroPython environment */
void perform_system_cleanup(void) {
    /* 1. Stop any ongoing network activity first */
    ca_upy_net_reset();

    /* 2. Close all sockets to free up memory and descriptors */
    ca_upy_sock_reset();

    /* 3. Reset file system handles */
    ca_upy_fs_reset();

    /* 4. Finally, reset synchronization primitives */
    ca_upy_sync_reset();

    /* Log the event to the console */
    ca_stdout_put_str("System resources cleaned up successfully.\r\n");
}

