    /* Check if the requested endpoint is stalled */
    bool stalled = ca_usb_ep_is_stalled(usb_num, ep_addr);

    /* Prepare status response: bit 0 is stall status */
    u8 status[2] = { stalled ? 0x01U : 0x00U, 0x00U };

