/* Example: Sending a buffer via USB NCM */
void send_data_example(u8 *data, u16 size, u32 cookie) {
    u32 usb_idx = ca_usb_dev_mng_get_num();

    /* Ensure scheduler is locked to maintain atomicity during buffer handoff */
    ca_os_sched_lock();

    /* Attempt to queue the buffer for zero-copy transmission */
    bool success = ca_usb_ep_write_ref(usb_idx, 0x81, data, size, my_release_callback, cookie);

    ca_os_sched_unlock();

    if (!success) {
        /* If queuing failed, we still own the buffer; free it immediately */
        ca_memory_free(data);
    }
}

/* Callback invoked by the USB stack when transmission is complete */
void my_release_callback(const u8 *buf, u32 cookie) {
    /* Safely free the buffer now that the USB hardware is done with it */
    ca_memory_free((void*)buf);
}

