void handle_usb_setup_request(u32 usb_num, u8 request, u16 value) {
    /* 0x05U is the standard USB_REQ_SET_ADDRESS code */
    if (request == 0x05U) {
        u8 new_addr = (u8)(value & 0x7FU);

        /* Apply the new address to the USB hardware */
        ca_usb_set_address(usb_num, new_addr);

        /* Send a zero-length status packet to acknowledge the request */
        /* Note: ca_usb_ep_write is used to complete the control transfer */
        ca_usb_ep_write(usb_num, 0x80U, (u8*)0, 0U);
    }
}

