ca_spinlock_t my_lock;

void task_wait_for_resource(void) {
    ca_thread_context_t *ctx = ca_scheduler_get_current_context();

    ca_spinlock_lock_irq(&my_lock);

    /* Check if resource is available */
    if (resource_is_empty()) {
        /* Enqueue the current task to the wait queue */
        ca_wait_queue_enqueue(&my_wq, ctx);

        /* Prepare to block and release the lock */
        ca_os_wait_prepare();
        ca_spinlock_unlock_irq(&my_lock);

        /* Yield CPU to other tasks until signaled */
        ca_os_yield();
    } else {
        ca_spinlock_unlock_irq(&my_lock);
    }
}

