    /* Query the hardware limit for the IWDG */
    u32 max_limit = ca_wdt_max_timeout_ms(wdt_type);

    if (requested_ms > 0U && requested_ms <= max_limit) {
        /* Configuration is within hardware limits, proceed to init */
        bool success = ca_wdt_init(requested_ms, CA_WDT_MODE_RESET, wdt_type);
        if (success) {
            ca_stdout_put_n("Watchdog initialized successfully");
        }
    } else {
        /* Log error: requested timeout is out of hardware range */
        ca_stdout_put_n("Error: Requested WDT timeout exceeds hardware limit");
    }
}

