/* Define the early warning callback */
void my_early_warning_cb(void *arg) {
    /* Save the error type to backup registers before reset */
    ca_bkp_write(0U, (uint32_t)arg);
}

void setup_watchdog(void) {
    /* Register the callback to run before the WDT resets the system */
    ca_wdt_on_early(my_early_warning_cb, (void *)0xDEADBEEF);

    /* Initialize WDT with interrupt mode to allow the callback to run */
    if (ca_wdt_init(1000U, CA_WDT_MODE_INTERRUPT, 0U)) {
        ca_wdt_enable();
    }
}

