ca_hash_ctx_t.example:
ca_hash_ctx_t ctx;
u8 data_chunk[] = {0x01, 0x02, 0x03};
u8 digest[32];

/* Initialize the hashing context */
ca_hash_ctx_init(&ctx, CA_HASH_SHA256);

/* Feed data into the context */
ca_hash_ctx_update(&ctx, data_chunk, sizeof(data_chunk));

