ca_hmac_sha256_ctx_t.example:
#include "caos/crypto/inc/kdf.h"

void compute_hmac(uint8_t *key, size_t key_len, uint8_t *data, size_t data_len) {
    ca_hmac_sha256_ctx_t ctx;
    uint8_t digest[32];

    /* Initialize the HMAC context with the provided key */
    ca_hmac_sha256_init(&ctx, key, key_len);

    /* Process the data stream */
    ca_hmac_sha256_update(&ctx, data, data_len);

    /* Finalize the HMAC and store the result in digest */
    ca_hmac_sha256_final(&ctx, digest);
}

