ca_ip_defrag_stats_t.body:
typedef struct {
u32 frags;       /* fragments accepted into a session                  */
u32 complete;    /* datagrams reassembled and injected                 */
u32 timeout;     /* sessions dropped incomplete after the timeout      */
u32 drop_bad;    /* fragment refused: malformed, too big, contradicts  */
u32 drop_full;   /* fragment refused: every session slot busy          */
u32 drop_big;    /* reassembled datagram does not fit a net_buf        */
u16 partial;     /* sessions open right now (filled by the read)       */
} ca_ip_defrag_stats_t;

ca_ip_defrag_stats_t.example:
#include "caos/net/inc/ip_defrag.h"

void print_ip_stats(void) {
    ca_ip_defrag_stats_t stats;

    /* Retrieve current fragmentation statistics */
    ca_ip_defrag_stats(&stats);

    ca_printf("IP Defrag Stats:\n");
    ca_printf("Complete: %u\n", stats.complete);
    ca_printf("Dropped (Full): %u\n", stats.drop_full);
    ca_printf("Active Sessions: %u\n", stats.partial);
}

ca_ip_frag_stats_t.example:
#include "caos/net/inc/ip_frag.h"

void check_network_health(void) {
    ca_ip_frag_stats_t stats;

    /* Retrieve current fragmentation statistics from the stack */
    ca_ip_frag_stats(&stats);

    if (stats.drop_df > 0) {
        ca_printf("Warning: Packets dropped due to MTU/DF settings: %lu\n", stats.drop_df);
    }

    /* Reset statistics after reading to monitor a new interval */
    ca_ip_frag_stats_reset();
}

