ca_net_queue_t.body:
typedef struct {
u16          buf[NET_QUEUE_DEPTH];
volatile u16 head;    /* consumer (net task) advances head */
volatile u16 tail;    /* producer (ISR)      advances tail */
} ca_net_queue_t;

ca_net_queue_t.example:
ca_net_queue_t rx_queue;

void init_queue(void) {
    rx_queue.head = 0;
    rx_queue.tail = 0;
}

/* Inside ISR */
void HAL_ETH_RxCpltCallback(void) {
    rx_queue.buf[rx_queue.tail] = new_packet_id;
    rx_queue.tail = (rx_queue.tail + 1) % NET_QUEUE_DEPTH;
}

/* Inside Network Task */
void net_task(void *p) {
    while(1) {
        if(rx_queue.head != rx_queue.tail) {
            u16 packet = rx_queue.buf[rx_queue.head];
            rx_queue.head = (rx_queue.head + 1) % NET_QUEUE_DEPTH;
            process_packet(packet);
        }
    }
}

