ca_sha256_ctx_t.body:
typedef struct {
u32 state[8];                   /* Internal state H0..H7 */
u64 bitlen;                     /* Message length in bits (64 bits) */
u8  buffer[SHA256_BLOCK_SIZE];  /* Partial block in accumulation */
u32 buflen;                     /* Valid bytes in buffer */
u32 W[64];                      /* Message schedule — in ctx, not on stack:
* SW compression is deep and on targets
* without HW HASH (F407) it would burden the stack. */
} ca_sha256_ctx_t;

ca_sha512_ctx_t.body:
typedef struct {
u64 state[8];                   /* Internal state H0..H7 */
u64 bitlen_lo;                  /* Message length in bits (low part) */
u64 bitlen_hi;                  /* Message length in bits (high part) */
u8  buffer[SHA512_BLOCK_SIZE];  /* Partial block in accumulation */
u32 buflen;                     /* Valid bytes in buffer */
u64 W[80];                      /* Message schedule — in ctx, not on stack:
* 640B that would burden the task stack
* (Ed25519 calls SHA-512 deeply). */
} ca_sha512_ctx_t;

