ca_x25519_ctx_t.example:
#include "caos/crypto/inc/x25519.h"

void generate_public_key(void) {
    ca_x25519_ctx_t ctx;
    u8 public_key[32];

    /* Initialize private key scalar in ctx.e */
    ca_memset(ctx.e, 0x42, 32);

    /* Compute public key from the scalar stored in ctx */
    ca_x25519_base(public_key, ctx.e);

    /* public_key now contains the result */
}
